package dev.pocketengine.store;

import dev.pocketengine.core.RunControl;
import dev.pocketengine.runtime.routes.PhoneRouteSession;
import org.json.JSONArray;
import org.json.JSONObject;

/** Read-only route suggestions and withdrawal events in the original TaskStore, without another database. */
public final class TaskStorePhoneRoutes implements PhoneRouteSession.Repository {
    public interface Versions {long version(String packageName)throws Exception;}
    private final TaskStore tasks;private final String task;private final RunControl original;private final Versions versions;
    public TaskStorePhoneRoutes(TaskStore tasks,String task,RunControl original,Versions versions)throws Exception {this.tasks=java.util.Objects.requireNonNull(tasks);this.task=task;this.original=original;this.versions=java.util.Objects.requireNonNull(versions);current(original);}
    private void current(RunControl live)throws Exception {if(live!=original||!live.hasHostRun()||live.isPaused())throw new SecurityException("路线目录不属于本次原运行");live.check();JSONObject actual=tasks.get(task,false);if(actual==null||actual.optJSONObject("origin")!=null||!"owner".equals(actual.optString("actorId"))||!"private".equals(actual.optString("spaceId"))||!live.matchesHostRun(task,actual.optString("runId"),actual.optInt("coordinatorEpoch")))throw new SecurityException("路线只对本机主人私人原任务开放");}
    public JSONArray routes(String goal,RunControl live)throws Exception {current(live);JSONArray rows=tasks.list(),result=new JSONArray();for(int i=0;i<rows.length()&&result.length()<32;i++){JSONObject row=rows.getJSONObject(i),candidate=eligible(tasks.get(row.getString("id"),false));if(candidate!=null&&sameGoal(goal,candidate.getString("goal")))result.put(new JSONObject().put("routeId",candidate.getString("routeId")).put("digest",candidate.getString("digest")).put("packageName",candidate.getString("packageName")).put("packageVersion",candidate.getLong("packageVersion")).put("steps",candidate.getJSONArray("steps").length()).put("ownerConfirmed",true));}current(live);return result;}
    public JSONObject route(String id,String digest,String goal,RunControl live)throws Exception {current(live);JSONArray rows=tasks.list();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);JSONObject candidate=eligible(tasks.get(row.getString("id"),false));if(candidate!=null&&id.equals(candidate.getString("routeId"))&&digest.equals(candidate.getString("digest"))&&sameGoal(goal,candidate.getString("goal"))){current(live);return candidate;}}throw new SecurityException("原成功路线已撤回、变版或不匹配此精确目标");}
    public void withdraw(String id,String digest,RunControl live)throws Exception {current(live);JSONArray rows=tasks.list();for(int i=0;i<rows.length();i++){JSONObject source=tasks.get(rows.getJSONObject(i).getString("id"),false),candidate=eligible(source);if(candidate!=null&&id.equals(candidate.getString("routeId"))&&digest.equals(candidate.getString("digest"))){tasks.event(source.getString("id"),new JSONObject().put("type","phone_route_withdrawn").put("routeId",id).put("digest",digest).put("byTaskId",task));current(live);return;}}throw new SecurityException("需要当前目录中的准确路线版本");}
    public long packageVersion(String packageName)throws Exception{return versions.version(packageName);}
    private static boolean sameGoal(String first,String second){return first.trim().replaceAll("\\s+"," ").equals(second.trim().replaceAll("\\s+"," "));}
    static JSONObject eligible(JSONObject task)throws Exception {
        if(task==null||task.optJSONObject("origin")!=null||!"owner".equals(task.optString("actorId"))||!"private".equals(task.optString("spaceId")))return null;JSONObject evidence=task.optJSONObject("evidence"),route=evidence==null?null:evidence.optJSONObject("nativePhoneRoute");
        if(route==null||!"pocketworld.phone-route-candidate.v1".equals(route.optString("format"))||!task.getString("id").equals(route.optString("sourceTaskId"))||!task.optString("runId").equals(route.optString("sourceRunId"))||task.optInt("coordinatorEpoch")!=route.optInt("sourceEpoch")||!route.optString("digest").equals(PhoneRouteSession.digest(route)))return null;
        boolean verified=false;JSONArray events=task.optJSONArray("events");for(int i=0;events!=null&&i<events.length();i++){JSONObject event=events.getJSONObject(i);if("phone_route_withdrawn".equals(event.optString("type"))&&route.getString("routeId").equals(event.optString("routeId"))&&route.getString("digest").equals(event.optString("digest")))return null;if("user_verification".equals(event.optString("type"))&&route.getString("sourceRunId").equals(event.optString("runId"))&&route.getInt("sourceEpoch")==event.optInt("coordinatorEpoch"))verified=event.optBoolean("completed");}
        JSONArray expected=route.optJSONArray("operationIds"),steps=route.optJSONArray("steps"),operations=task.optJSONArray("operations");if(!verified||expected==null||steps==null||expected.length()!=steps.length()||steps.length()<1||steps.length()>4||operations==null)return null;
        java.util.Set<String> found=new java.util.HashSet<>();for(int i=0;i<operations.length();i++){JSONObject op=operations.getJSONObject(i);if(op.optString("state").matches("prepared|unknown"))return null;for(int j=0;j<expected.length();j++)if(expected.getString(j).equals(op.optString("operationId"))){JSONObject receipt=op.optJSONObject("receipt");if(!"receipt".equals(op.optString("state"))||!route.getString("sourceRunId").equals(op.optString("runId"))||!steps.getJSONObject(j).getString("tool").equals(op.optString("tool"))||receipt==null||!Boolean.TRUE.equals(receipt.opt("ok"))||receipt.has("accepted")&&!Boolean.TRUE.equals(receipt.opt("accepted"))||!found.add(op.getString("operationId")))return null;}}
        return found.size()==expected.length()?new JSONObject(route.toString()):null;
    }
}
